set +e; export DEBIAN_FRONTEND=noninteractive; SU=""; [ "$(id -u)" = "0" ] || SU="sudo"; if [ -f /etc/apt/sources.list.d/debian.sources ]; then $SU sed -i 's/^Components:.*/Components: main contrib non-free non-free-firmware/' /etc/apt/sources.list.d/debian.sources; elif [ -f /etc/apt/sources.list ]; then $SU sed -i 's/ main$/ main contrib non-free non-free-firmware/' /etc/apt/sources.list; fi; $SU apt-get update -y >/dev/null 2>&1; $SU apt-get install -y --no-install-recommends tesseract-ocr poppler-utils libreoffice libreoffice-writer libreoffice-calc libreoffice-impress pandoc imagemagick ghostscript unzip zip p7zip-full fonts-liberation fonts-dejavu >/dev/null 2>&1; for p in nmap curl wget git jq whois dnsutils netcat-openbsd net-tools iputils-ping openssl sqlite3 hashcat hydra john python3-pip build-essential; do $SU apt-get install -y --no-install-recommends "$p" >/dev/null 2>&1; done; (python3 -m pip install -q --break-system-packages img2pdf >/dev/null 2>&1 || python3 -m pip install -q img2pdf >/dev/null 2>&1) || true; touch /home/user/work/.tools_prewarmed; echo PREWARM_DONE